package ui;

import model.Notice;import service.CategoryService;import service.DepartmentService;import service.UserService;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.time.format.DateTimeFormatter;

public class NoticeDetailsFrame extends JFrame {
    private final Notice notice;private final CategoryService categoryService;private final UserService userService;private final DepartmentService departmentService;
    public NoticeDetailsFrame(Notice n,CategoryService c,UserService u,DepartmentService d){notice=n;categoryService=c;userService=u;departmentService=d;UITheme.styleFrame(this,"Notice Details",800,650);setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);createUI();setVisible(true);}
    private void createUI(){JPanel root=new JPanel(new BorderLayout(0,18));root.setBackground(UITheme.BG);root.setBorder(BorderFactory.createEmptyBorder(22,28,22,28));JPanel head=UITheme.card();head.setLayout(new BorderLayout(12,8));JPanel text=new JPanel();text.setOpaque(false);text.setLayout(new BoxLayout(text,BoxLayout.Y_AXIS));text.add(UITheme.title(notice.getTitle(),25));text.add(Box.createVerticalStrut(7));text.add(UITheme.muted("Published notice • Notice ID #"+notice.getNoticeId()));head.add(text,BorderLayout.CENTER);JLabel badge=UITheme.badge(notice.getStatus());UITheme.colorBadge(badge,notice.getStatus());head.add(badge,BorderLayout.EAST);root.add(head,BorderLayout.NORTH);
        JPanel info=UITheme.card();info.setLayout(new GridLayout(4,4,10,12));addInfo(info,"Category",categoryService.getCategoryNameById(notice.getCategoryId()));addInfo(info,"Created By",userService.getUserNameById(notice.getCreatedBy()));addInfo(info,"Department",notice.getDepartmentId()==null?"All Departments":departmentService.getDepartmentNameById(notice.getDepartmentId()));addInfo(info,"Priority",notice.getPriority());addInfo(info,"Status",notice.getStatus());addInfo(info,"Publish Date",formatDate(notice.getPublishAt()));addInfo(info,"Expiry Date",formatDate(notice.getExpiresAt()));addInfo(info,"Created",formatDate(notice.getCreatedAt()));
        JPanel center=new JPanel(new BorderLayout(0,12));center.setOpaque(false);center.add(info,BorderLayout.NORTH);JPanel desc=UITheme.card();desc.setLayout(new BorderLayout(0,10));desc.add(UITheme.title("Description",16),BorderLayout.NORTH);JTextArea area=new JTextArea(notice.getDescription());area.setFont(UITheme.font(14,Font.PLAIN));area.setForeground(UITheme.TEXT);area.setBackground(Color.WHITE);area.setLineWrap(true);area.setWrapStyleWord(true);area.setEditable(false);area.setBorder(new EmptyBorder(4,4,4,4));desc.add(new JScrollPane(area),BorderLayout.CENTER);center.add(desc,BorderLayout.CENTER);root.add(center,BorderLayout.CENTER);JButton close=UITheme.button("Close",false);close.addActionListener(e->dispose());JPanel bottom=new JPanel(new FlowLayout(FlowLayout.RIGHT));bottom.setOpaque(false);bottom.add(close);root.add(bottom,BorderLayout.SOUTH);setContentPane(root);}
    private void addInfo(JPanel p,String label,String value){JLabel l=new JLabel("<html><b>"+label+"</b><br><span style='color:#6B7280'>"+value+"</span></html>");p.add(l);}
    private String formatDate(java.time.LocalDateTime d){return d==null?"Not specified":d.format(DateTimeFormatter.ofPattern("dd MMM yyyy, HH:mm"));}
}
